from __future__ import absolute_import
from taf.selenium.sbts.pages import v21a
from selenium.webdriver.common.by import By


class RndMode(v21a.RndMode):
    def __init__(self, driver, download_checker):
        super(RndMode, self).__init__(driver, download_checker)
        self._fiveg_performance_test = NrPerformanceTestPage(driver)


class NrPerformanceTestPage(v21a.rnd_mode.NrPerformanceTestPage):
    _MENU_ROUTE_LIST = ['R&D Mode', 'NR Performance Test']

    def __init__(self, driver):
        super(NrPerformanceTestPage, self).__init__(driver)
        self._view_panel = NrPerformanceTestPageViewPanel(driver)


class NrPerformanceTestPageViewPanel(v21a.rnd_mode.NrPerformanceTestPageViewPanel):
    _NUMBER_OF_UCI_BITS = '//div[contains(text(), "Number of UCI bits")]/parent::*//input'
    _PAYLOAD_OF_CSI_BITS = '//div[contains(text(), "Payload of CSI bits")]/parent::*//input'

    def __init__(self, driver):
        super(NrPerformanceTestPageViewPanel, self).__init__(driver)

    def _configure_uci_bits_number(self):
        uci_bits_number = getattr(self, 'uci_bits_number')
        if uci_bits_number is not None:
            self.insert_text_to_enable_element(
                (By.XPATH, self._NUMBER_OF_UCI_BITS),
                uci_bits_number)

    def _setup_common_params(self, *args, **kwargs):
        super(NrPerformanceTestPageViewPanel, self)._setup_common_params(*args, **kwargs)
        if kwargs['test_type'] == 'PUSCH':
            self._configure_uci_bits_number()
            self._configure_multiple_input(getattr(self, 'csi_bits_payload'), self._PAYLOAD_OF_CSI_BITS)

    def start_pusch_test(self, local_cell, frc_index, do_rate, do_type, rep_time_int, beam_id=None, ru_mode=None,
                         physical_cell_id=None, bb_selector=None, prb_offset=None, nrarfcn_downlink=None,
                         nrarfcn_uplink=None, nrarfcn=None, uci_bits_number=None, csi_bits_payload=None, timeout=15):
        setattr(self, 'uci_bits_number', uci_bits_number)
        setattr(self, 'csi_bits_payload', csi_bits_payload)
        super(NrPerformanceTestPageViewPanel, self).start_pusch_test(local_cell=local_cell,
                                                                     frc_index=frc_index,
                                                                     do_rate=do_rate,
                                                                     do_type=do_type,
                                                                     rep_time_int=rep_time_int,
                                                                     beam_id=beam_id,
                                                                     ru_mode=ru_mode,
                                                                     physical_cell_id=physical_cell_id,
                                                                     bb_selector=bb_selector,
                                                                     prb_offset=prb_offset,
                                                                     nrarfcn_downlink=nrarfcn_downlink,
                                                                     nrarfcn_uplink=nrarfcn_uplink,
                                                                     nrarfcn=nrarfcn,
                                                                     timeout=int(timeout))
